 const types={REQUEST:'诉求',FACT:'事实用途绑定',SOURCE:'来源集合',SERVICE_RULE:'服务资料要求',RESOURCE:'资源规则',CAPACITY_SNAPSHOT:'容量快照',PLAN_STEP:'办理步骤',RESERVATION:'预约',MATERIAL:'材料聚合',RECEIPT:'回执',CHECK:'检查',RELEASE:'定义版本'};
 const facets={CASE_BINDING:'事项范围',REQUEST_INTENT:'已确认诉求',MATERIAL_PACKAGE:'已核对材料版本',FACT_PURPOSE_BINDING:'选定事实及用途',SERVICE_RULE:'所用服务资料要求',OWNER_AUTHORITY:'本人当前办理权',RESOURCE_ASSOCIATION:'关联资源',RESOURCE_RULES:'所用资源规则',RESERVATION_SOURCES:'预约及有效期',RESOURCE_AUTHORITY:'所用资源权限',RESOURCE_CATALOG_DECISION:'资源目录选择',RESOURCE_QUERY_SET:'当前可选资源集合',DISPATCH_ACCEPTANCE:'分派及本人接单',RUN_ACCESS_QUERY_SET:'当前运行访问集合',RECEIPT_SOURCE:'所用回执版本',RECEIPT_EVENTS:'回执核对记录',LOCAL_CHECK:'本地事项复核',TEMPLATE_SOURCE:'所用模板来源',TEMPLATE_STRUCTURES:'已采纳模板结构',DEPENDENCY_RESOURCE_QUERY_SET:'可用资源集合基线',DEPENDENCY_RUN_ACCESS_QUERY_SET:'运行访问集合基线',UNMAPPED_SOURCE_FIELDS:'尚不能解释的来源'};
 target.append(textElement('p','本次需重验：'+names(graph.affected)+'；本次保持：'+names(graph.preserved)),textElement('p','只比较原核验与当前实际读取的有限来源。聚合证明不等于逐份材料真实性；适用日期缺证据时保持未知。'));
