  const field=$('case-fact-source-field').value;
  if(!caseFactFields[field])throw Error('未知字段');
  const text=$('case-fact-source-value').value.trim();
  const value=field==='employees'?Number(text):text;
  if(!text||(field==='employees'&&(!/^\d+$/.test(text)||!Number.isSafeInteger(value)||value<0)))throw Error('员工人数须为非负整数，其余字段须填写自述');
