  prepRole=x.role;const reasons={CASE_CANCELLED:'事项已撤销，仅保留历史',CASE_RECONCILING:'撤销结果待核对，新办理暂停',LOCAL_RECORD_CLOSED:'本地记录已关闭',REQUEST_CHANGED:'诉求或方案已变化',SERVICE_CHANGED:'资料服务版本已变化',CATALOG_CHANGED:'服务目录已变化',REGISTRY_CHANGED:'能力说明已变化',MATERIAL_REFERENCE_INTEGRITY_REQUIRED:'材料引用无法核实',MANUAL_HISTORY_LIMIT_REACHED:'人工协作记录达到上限',CURRENT_WRITE_AUTHORITY_REQUIRED:'当前权限不允许写入',SUPPLEMENT_REFERENCE_STALE:'补证引用已换版',MANUAL_JOURNAL_UNVERIFIED:'人工记录无法核实',REPLY_SOURCE_CHANGED:'答复来源已变化，不能据旧答复结束责任'},humanStates={REQUESTED:'待原专员本人接责',UNDER_MANUAL_REVIEW:'原专员核对中',WAITING_OWNER_EVIDENCE:'待企业补证',AWAITING_SPECIALIST_REVIEW:'补证已交，待专员核对',UNKNOWN:'记录状态待核对',WAITING_OWNER_ACKNOWLEDGEMENT:'待企业知悉精确答复',RECHECK_REQUESTED:'仅申请，待原专员明确接续',UNDER_MANUAL_RECHECK:'原专员已明确接续再核对'};const target=$('prep-task-items');target.append(textElement('p',x.role==='enterprise_operator'?'企业待办':'原获派专员待办'));
