async function loadMaterialCorrections(context){requirePrepCurrent(context);try{const x=await prepCall('/api/preparations/'+encodeURIComponent(context.id)+'/material-corrections','GET',undefined,undefined,context);if(x.preparation_id!==context.id||x.case_id!==preparationContext?.caseId||x.preparation_revision!==preparationView?.preparation.revision)throw Error('补正来源与资料版本不匹配，请刷新');renderMaterialCorrections(x);}catch(e){if(e.status===403){prepError(e);return;}if(prepCurrent(context)){$('material-corrections-error').textContent=e.message;if(prepRole==='park_specialist')$('prep-review').disabled=true;}}}
function renderPrepCommandPending(){const submitting=prepCommandPending?.state==='SUBMITTING',unknown=prepCommandPending?.state==='UNKNOWN';$('prep-command-retry').hidden=!unknown;$('prep-command-retry').disabled=!!submitting;$('prep-command-feedback').textContent=submitting?'正在提交材料操作，请等待结果。':unknown?'操作结果尚未核实。保留了原参数与请求编号，核对前请勿提交另一操作。':'';$('prep-refresh').disabled=!!prepCommandPending;$('readiness-assess').disabled=!!prepCommandPending||!!(readinessView?.history.length>=32);for(const button of document.querySelectorAll('#prep-evidence button,#prep-decision button,[data-correction-respond]'))button.disabled=!!(submitting||unknown);if(!submitting&&!unknown&&materialCorrectionsView&&prepRole==='park_specialist'){$('prep-review').disabled=!materialCorrectionsView.can_review;$('prep-correction').disabled=!materialCorrectionsView.can_request_changes;}for(const form of ['case-resource-form','receipt-create'])for(const el of $(form).elements)el.disabled=!!prepCommandPending;renderMaterialReuseControls();renderCaseFactControls();renderMaterialDraftControls();renderPrepRecovery();if(materialPackLocked())clearMaterialPack();else renderMaterialPackControls();}
function sameJsonValue(a,b){if(a===b)return true;if(a===null||b===null||typeof a!==typeof b||typeof a!=='object'||Array.isArray(a)!==Array.isArray(b))return false;if(Array.isArray(a))return a.length===b.length&&a.every((v,i)=>sameJsonValue(v,b[i]));const keys=Object.keys(a);return keys.length===Object.keys(b).length&&keys.every(k=>Object.hasOwn(b,k)&&sameJsonValue(a[k],b[k]));}
async function sendPrepCommand(pending){let context=pending.context;requirePrepCurrent(context);rememberPrepRecovery(pending);prepCommandPending=pending;pending.state='SUBMITTING';renderPrepCommandPending();try{const committed=await prepCall(pending.path,'POST',pending.body,pending.key,context);pending.commitObserved=true;requirePrepCurrent(context);const actual=await prepCall('/api/preparations/'+encodeURIComponent(context.id),'GET',undefined,undefined,context);if(committed.preparation_id!==context.id||committed.case_id!==context.caseId||committed.action!==pending.body.action||committed.revision!==pending.body.expected_revision+1||!actual.history.some(e=>e.revision===committed.revision&&e.action===committed.action&&Object.keys(committed).length===Object.keys(e.payload).length&&Object.keys(committed).every(k=>sameJsonValue(e.payload[k],committed[k]))))throw Error('未核对到原操作的精确保存事件，保留原请求');await loadPreparation(context.id,{verifiedCommand:pending,verifiedSnapshot:actual});forgetPrepRecovery(pending.key);prepCommandPending=null;renderPrepCommandPending();if(preparationDraft()===pending.draft){$('prep-text').value='';$('prep-reason').value='';if(pending.body.action==='REQUEST_CHANGES')for(const input of document.querySelectorAll('[data-correction-slot]'))input.checked=false;}$('prep-command-feedback').textContent='已核对原操作保存事件；下方显示当前资料，提交新版仍须原专员独立核对。';}catch(e){if(context.token!==$('token').value||context.id!==preparationId)throw e;pending.context={...prepContext(),caseId:context.caseId,revision:context.revision};if(e.status===403||e.status===409||e.status===422){if(e.status!==403&&!pending.commitObserved)forgetPrepRecovery(pending.key);prepCommandPending=null;clearMaterialCorrections();clearReadiness();if(e.status!==403){preparationView=null;preparationContext=null;}}else{pending.state='UNKNOWN';if(pending.body.action==='ADD_EVIDENCE')prepRecoveryHandle=readPrepRecovery(context.id);clearMaterialDraft();clearMaterialCorrections();clearReadiness();$('prep-materials').replaceChildren();$('prep-history').replaceChildren();$('prep-summary').textContent='材料操作结果未知；当前状态和版本待原请求核对。';}renderPrepCommandPending();throw e;}}
async function prepCommand(action){if(objectionLock())throw Error("请先核对原异议操作");if(prepRecoveryHandle||prepRecoveryChecking)throw Error('请先只读核对原材料提交');if(caseFactPending)throw Error('请先以原参数核对事实用途结果');if(materialReusePending)throw Error('请先以原操作核对材料复用结果');if(prepCommandPending)throw Error('请先核对当前未知操作结果');if(!preparationView||!preparationContext)throw Error('请先读取当前事项');const context=preparationContext;requirePrepCurrent(context);const p=preparationView.preparation;if(p.id!==context.id||p.case_id!==context.caseId||p.revision!==context.revision||!Number.isInteger(p.revision))throw Error('事项版本不匹配，请刷新核对');const draft=preparationDraft();const body={action,expected_revision:p.revision};if(action==='ADD_EVIDENCE'){Object.assign(body,{slot:$('prep-slot').value,text:$('prep-text').value,source_kind:$('prep-source-kind').value,source_label:$('prep-source-label').value});}else{body.reason=$('prep-reason').value;if(!body.reason.trim())throw Error('请填写人工说明');if(action==='REQUEST_CHANGES'){const slots=Array.from(document.querySelectorAll('[data-correction-slot]:checked')).map(x=>x.dataset.correctionSlot);if(slots.length)body.correction_slots=slots;}}const path='/api/preparations/'+encodeURIComponent(context.id)+'/commands',signature=path+JSON.stringify(body);let key=prepRetries.get(signature);if(!key){key=crypto.randomUUID();prepRetries.set(signature,key);}return sendPrepCommand({context,body:JSON.parse(JSON.stringify(body)),key,path,draft,state:'SUBMITTING'});}
$('prep-command-retry').onclick=()=>{const pending=prepCommandPending;if(!pending||pending.state!=='UNKNOWN')return;const context=prepContext();if(context.id!==pending.context.id||context.token!==pending.context.token)return;pending.context={...context,caseId:pending.context.caseId,revision:pending.context.revision};(pending.materialDraft?sendMaterialDraft(pending):sendPrepCommand(pending)).catch(prepError);};
$('prep-evidence').onsubmit=e=>{e.preventDefault();return prepCommand('ADD_EVIDENCE').catch(prepError);};$('prep-decision').onsubmit=e=>e.preventDefault();
for(const [id,action] of [['prep-correction','REQUEST_CHANGES'],['prep-review','REVIEW'],['prep-confirm','CONFIRM'],['prep-reopen','REOPEN']])$(id).onclick=()=>prepCommand(action).catch(prepError);
