$('token').oninput=()=>{coldClear();const factUncertain=!!caseFactPending||!!prepCommandPending;clearRunAccess(true);clearGeneric(true);$('page-feedback').textContent='';clearPreparation(false,false,true);clearReceipts();clearResources();currentReview=null;lastClarification=null;$('questions').replaceChildren();$('clarifications').hidden=true;if(factUncertain)$('page-feedback').textContent='已清除原身份私有视图。原用途操作可能已提交；请回原身份、原事项读取历史后核对，勿重复新建操作。';};

