let resourceGeneration=0,resourcePreview=null;const resourceRetries=new Map();const combinationSelection=new Map();
function resourceDraft(){return JSON.stringify(['resource-select','resource-start','resource-end','resource-quantity','resource-ttl','resource-purpose','resource-search-from','resource-search-until'].map(id=>$(id).value));}
function resourceContext(){return {generation:resourceGeneration,token:$('token').value,id:$('resource-select').value||null,draft:resourceDraft()};}
function resourceCurrent(c){return c.generation===resourceGeneration&&c.token===$('token').value&&c.id===($('resource-select').value||null)&&c.draft===resourceDraft();}
function requireResourceCurrent(c){if(!resourceCurrent(c)){const e=Error('资源选择已变化');e.staleResource=true;throw e;}}
function clearResourceAlternatives(){$('resource-alternative-results').replaceChildren();}
function clearResources(){clearResourceAlternatives();bundleActor=null;bundleBusy=false;clearCombinationSelection();$('combination-items').replaceChildren();$('combination-feedback').textContent='';resourceGeneration++;resourcePreview=null;resourceRetries.clear();$('resource-form').reset();$('resource-form').hidden=true;$('resource-select').replaceChildren();for(const id of ['resource-catalog-view','resource-current','resource-hold-items'])$(id).replaceChildren();$('resource-preview-result').textContent='';$('resource-error').textContent='';$('resource-hold').disabled=true;}
function resourceError(e){if(e.staleResource||(e.resourceContext&&!resourceCurrent(e.resourceContext)))return;failCurrentEntryRead(e);if(e.status===403||e.status===401)clearResources();$('resource-error').textContent=e.message;$('page-feedback').dataset.tone='error';$('page-feedback').textContent=e.message;}
async function resourceCall(path,method='GET',body,key,c=resourceContext()){requireResourceCurrent(c);const headers={Authorization:'Bearer '+c.token};if(body)headers['Content-Type']='application/json';if(key)headers['Idempotency-Key']=key;let r,x;try{r=await entryFetch(path,{method,headers,body:body?JSON.stringify(body):undefined});x=await r.json();}catch(e){requireResourceCurrent(c);e.resourceContext=c;throw e;}requireResourceCurrent(c);if(!r.ok){const e=Error(r.status===409?(path.startsWith('/api/resource-combinations')?combinationFailure(x.detail):'容量、区间或规则已变化，请重新预检。'):r.status===403||r.status===401?'当前身份无此资源或占位权限。':r.status===422?'请检查UTC时间、数量和输入。':'请求未完成，可用相同输入重试或刷新核对。');e.status=r.status;e.resourceContext=c;throw e;}return x;}
async function resourceWrite(path,body,c){requireResourceCurrent(c);if(bundleLocked())throw Error('请先只读核对原组合操作');const signature=path+JSON.stringify(body);let key=resourceRetries.get(signature);if(!key){key=crypto.randomUUID();resourceRetries.set(signature,key);}const x=await resourceCall(path,'POST',body,key,c);resourceRetries.delete(signature);return x;}
function resourceWindow(){return {starts_at:$('resource-start').value+':00Z',ends_at:$('resource-end').value+':00Z',quantity:Number($('resource-quantity').value)};}
function resourceTime(value){const d=new Date(value);return Number.isNaN(d.getTime())?String(value):d.toISOString().slice(0,19).replace('T',' ');}
function resourceAlternativeBody(){return {...resourceWindow(),search_from:$('resource-search-from').value+':00Z',search_until:$('resource-search-until').value+':00Z'};}
function renderResourceAlternatives(x,c,body){
  const at=v=>new Date(v).getTime(),duration=at(body.ends_at)-at(body.starts_at),from=at(body.search_from),until=at(body.search_until);
  if(x.resource_id!==c.id||x.preview_only!==true||x.coverage!=='SEARCH_WINDOW_GRID_ONLY'||x.ordering!=='START_ASC'||x.grid_minutes!==15||x.scan_limit!==100||x.result_limit!==10||x.quantity!==body.quantity||at(x.starts_at)!==at(body.starts_at)||at(x.ends_at)!==at(body.ends_at)||at(x.search_from)!==from||at(x.search_until)!==until||at(x.grid_anchor)!==from||!Array.isArray(x.items)||x.items.length>10)throw Error('替代时段响应不匹配，请重新查找');
  let previous=-Infinity;
  for(const item of x.items){const start=at(item.starts_at),end=at(item.ends_at);if(!Number.isFinite(start)||!Number.isFinite(end)||start<=previous||start<from||end>until||end-start!==duration||(start-from)%900000!==0||item.quantity!==body.quantity)throw Error('替代时段响应不匹配，请重新查找');previous=start;}
  const target=$('resource-alternative-results');target.replaceChildren();
  target.append(textElement('p','本次数据库状态时间 '+x.server_time+'；窗口 '+resourceTime(x.search_from)+' — '+resourceTime(x.search_until)+' UTC。以起点每15分钟检查，扫描 '+x.scanned_candidates+' 个候选，最多返回最早10个。'+(x.results_truncated?'还有更晚的可用网格候选，可调整窗口继续查找。':'')));
  if(!x.items.length)target.append(textElement('p','所查网格未找到可用时段；这不表示所有时刻都不可用。可调整搜索窗口。'));
  for(const item of x.items){const button=textElement('button','填入 '+resourceTime(item.starts_at)+' — '+resourceTime(item.ends_at)+' UTC · '+item.quantity+'份');button.type='button';button.onclick=()=>{try{requireResourceCurrent(c);resourceGeneration++;resourcePreview=null;clearResourceAlternatives();$('resource-start').value=new Date(item.starts_at).toISOString().slice(0,16);$('resource-end').value=new Date(item.ends_at).toISOString().slice(0,16);$('resource-hold').disabled=true;$('resource-preview-result').textContent='已填入建议时段，请重新预检，再明确占位和确认。';$('resource-error').textContent='';}catch(e){resourceError(e);}};target.append(button);}
}
$('resource-alternatives').onclick=async()=>{
  clearResourceAlternatives();resourceGeneration++;resourcePreview=null;$('resource-hold').disabled=true;$('resource-preview-result').textContent='建议仅填表；占位前须重新预检。';const c=resourceContext(),body=resourceAlternativeBody();
  try{if(!c.id)throw Error('请先读取并选择合成资源');const x=await resourceCall('/api/synthetic-resources/'+encodeURIComponent(c.id)+'/alternative-times','POST',body,undefined,c);renderResourceAlternatives(x,c,body);$('resource-error').textContent='';}catch(e){resourceError(e);}
};
function renderResourceHold(h,target){const labels={HELD:'短期占位有效',CONFIRMED:'本地合成确认',EXPIRED:'占位已过期',RELEASED:'占位已释放 / 本地取消'};const card=textElement('article','');card.dataset.holdId=h.id;card.dataset.state=h.state;const badge=textElement('strong',labels[h.state]);badge.className='resource-state';const title=textElement('p',h.purpose);title.className='resource-title';const facts=textElement('dl','');facts.className='resource-facts';for(const [label,value] of [['合成资源',h.resource_name||'合成资源'],['使用区间（UTC）',resourceTime(h.starts_at)+' — '+resourceTime(h.ends_at)],['使用份数',h.quantity+'份'],['占位确认截止（历史，UTC）',resourceTime(h.expires_at)],['合成资源版本',String(h.resource_revision)]]){const field=textElement('div','');field.append(textElement('dt',label),textElement('dd',value));facts.append(field);}const boundary=textElement('p','本地合成状态；真实预约未确认，外部未受理，无线下履约。');boundary.className='boundary-note';card.append(badge,title,facts,boundary);if(h.combination_id){card.append(textElement('p','此记录属于资源组合，请在组合记录中整组取消。'));}else if(h.state==='HELD'||h.state==='CONFIRMED'){function command(action,label,body){const button=textElement('button',label);button.dataset.resourceAction=action;button.onclick=async()=>{resourceGeneration++;resourcePreview=null;$('resource-hold').disabled=true;const c=resourceContext();button.disabled=true;try{const x=await resourceWrite('/api/resource-holds/'+encodeURIComponent(h.id)+'/'+action,body,c);if(x.hold.id!==h.id)throw Error('占位响应不匹配，请刷新核对');const next=document.createElement('div');renderResourceHold(x.hold,next);card.replaceWith(next.firstElementChild);const historical=x.receipt&&x.receipt.observed_state!==x.hold.state?' 原操作回执为历史记录，当前状态以本次核对为准。':'';$('resource-preview-result').dataset.tone=x.hold.state==='CONFIRMED'?'success':x.hold.state==='RELEASED'?'neutral':'warning';$('resource-preview-result').textContent='当前状态：'+labels[x.hold.state]+'。'+historical+' 外部未受理，无线下履约。';$('resource-error').textContent='';$('page-feedback').dataset.tone='success';$('page-feedback').textContent='当前状态：'+labels[x.hold.state]+'。'+historical;resourcePreview=null;$('resource-hold').disabled=true;}catch(e){resourceError(e);if(resourceCurrent(c))button.disabled=false;}};card.append(button);}command('release',h.state==='CONFIRMED'?'取消此本地合成确认':'释放此占位',{});if(h.state==='HELD')command('confirm','确认此单资源合成占位',{expected_revision:h.resource_revision});}if(h.state==='HELD'&&!h.combination_id){const label=textElement('label','选入资源组合');label.className='combination-select';const check=document.createElement('input');check.type='checkbox';check.dataset.combinationHold=h.id;check.checked=combinationSelection.has(h.id);check.onchange=()=>{resourceGeneration++;resourcePreview=null;$('resource-hold').disabled=true;if(check.checked)combinationSelection.set(h.id,h);else combinationSelection.delete(h.id);updateCombinationSelection();};label.prepend(check);card.append(label);}target.append(card);}
