$('resource-preview').onclick=async()=>{clearResourceAlternatives();resourceGeneration++;resourcePreview=null;$('resource-hold').disabled=true;const c=resourceContext();try{if(!c.id)throw Error('请先读取并选择合成资源');const x=await resourceCall('/api/synthetic-resources/'+encodeURIComponent(c.id)+'/preview','POST',resourceWindow(),undefined,c);if(x.resource_id!==c.id)throw Error('资源响应不匹配，请重新读取');resourcePreview={view:x,context:c};$('page-feedback').textContent='';$('resource-preview-result').dataset.tone=x.available?'success':'warning';$('resource-preview-result').textContent=(x.available?'当前区间可尝试占位':'当前区间容量不足')+' · 当前峰值占用 '+x.occupied_peak+' / 容量 '+x.capacity+' · 可用 '+x.available_quantity+'份 · 本次状态时间 '+x.server_time+' · 预检不是预约';$('resource-hold').disabled=!x.available;$('resource-error').textContent='';}catch(e){resourceError(e);}};
