async function receiptCommand(action){if(receiptLocalPending)throw Error('本地执行结果未知，请先用原请求核对');if(!receiptView||!receiptContext)throw Error('请先读取当前回执事项');if(receiptView.case_write_blocked||receiptView.case_reconciling||(typeof caseReconBlocked==='function'&&caseReconBlocked(receiptView.step.case_id))||receiptView.case_cancelled||(preparationView?.case_cancelled&&preparationView.preparation.case_id===receiptView.step.case_id))throw Error('Case已取消，只能读取历史');const c=receiptContext;requireReceipt(c);const s=receiptView.step;if(s.id!==c.id||s.revision!==c.revision||(receiptView.current_receipt?.source_sha256||null)!==c.sha)throw Error('当前回执版本不匹配，请刷新');const draft=receiptDraft(),body={action,expected_revision:c.revision};if(action==='SUBMIT')Object.assign(body,{text:$('receipt-text').value,source_kind:'SYNTHETIC',source_label:$('receipt-source').value});else Object.assign(body,{reason:$('receipt-reason').value,receipt_sha256:c.sha});const path='/api/executor-receipts/'+encodeURIComponent(c.id)+'/commands',signature=path+JSON.stringify(body);let key=receiptRetries.get(signature);if(!key){key=crypto.randomUUID();receiptRetries.set(signature,key);}const result=await receiptCall(path,'POST',body,key,c);await loadReceipt(c.id);if(receiptDraft()===draft)resetReceiptDraft();if(result.event&&result.event.revision!==receiptView.step.revision)$('receipt-error').textContent='该输入的原始回执已记录；上方显示当前持久状态，请按当前版本核对。';}
$('receipt-submit').onsubmit=e=>{e.preventDefault();return receiptCommand('SUBMIT').catch(receiptError);};$('receipt-local-execution-form').onsubmit=e=>{e.preventDefault();return receiptLocalExecute(false).catch(receiptError);};$('receipt-local-execution-button').onclick=()=>receiptLocalExecute(false).catch(receiptError);$('receipt-local-execution-retry').onclick=()=>receiptLocalExecute(true).catch(receiptError);document.addEventListener('click',e=>{if(!receiptLocalPending)return;const t=e.target instanceof Element?e.target:null;if(!t||t.closest('#receipt-local-execution-retry,#token'))return;if(t.closest('button,[data-tab],a')){e.preventDefault();e.stopImmediatePropagation();$('receipt-local-execution-error').textContent='本地执行结果未知；请先使用原请求重试。切换页面或角色会清除此身份的私有请求状态。';}},true);$('receipt-decisions').onsubmit=e=>e.preventDefault();for(const [id,action] of [['receipt-ack','ACKNOWLEDGE'],['receipt-correct','REQUEST_CHANGES'],['receipt-reopen','REOPEN']])$(id).onclick=()=>receiptCommand(action).catch(receiptError);
$('receipt-refresh').onclick=()=>receiptLocalPending?($('receipt-local-execution-error').textContent='本地执行结果未知；请使用原请求重试并核对。'):loadReceipt(receiptId).catch(receiptError);
let receiptCreateContext=null;
$('receipt-prepare').onclick=async()=>{try{if(!preparationContext||preparationView?.preparation.state!=='LOCAL_CONFIRMED')throw Error('请先读取已本地确认的资料');const c=preparationContext,x=await prepCall('/api/executor-receipts/catalog?preparation_id='+encodeURIComponent(c.id),'GET',undefined,undefined,c);receiptCreateContext={...c,revision:preparationView.preparation.revision};$('receipt-executor').replaceChildren();for(const e of x.executors){const o=textElement('option',e.id);o.value=e.id;$('receipt-executor').append(o);}$('receipt-create').hidden=!x.ready||!x.executors.length;if(!x.executors.length)$('prep-error').textContent='此运行暂无合法获派执行者；这里只读取已有分配。';}catch(e){prepError(e);}};
