function clearCaseResources(){clearBoundedCaseReads();caseResourceGeneration++;caseResourceView=null;caseResourceContext=null;caseResourceRetries.clear();$('case-resource-panel').hidden=true;$('case-resource-form').reset();$('case-resource-choice').replaceChildren();$('case-resource-summary').textContent='';$('case-resource-history').replaceChildren();$('case-resource-error').textContent='';}
function caseResourceDraft(){return JSON.stringify([$('case-resource-choice').value,$('case-resource-reason').value]);}
function caseResourceCurrent(c){return prepCurrent(c)&&c.linkGeneration===caseResourceGeneration;}
function requireCaseResource(c){if(!caseResourceCurrent(c)){const e=Error('已离开原Case资源关联');e.staleCaseResource=true;throw e;}}
