const resourceExecutionPreviewStorage='parkweave.resource-execution-preview-recovery.v1';
function validResourceExecutionPreviewHandle(h){return h&&typeof h==='object'&&!Array.isArray(h)&&Object.keys(h).sort().join(',')==='expires,key,preparation,revision,source'&&/^[a-f0-9-]{36}$/.test(h.preparation)&&/^[a-zA-Z0-9:_-]{1,100}$/.test(h.key)&&Number.isInteger(h.revision)&&h.revision>0&&h.revision<=64&&/^[a-f0-9]{64}$/.test(h.source)&&Number.isInteger(h.expires)&&h.expires>Date.now()&&h.expires<=Date.now()+86400000;}
function resourceExecutionPreviewHandles(){let rows;try{const raw=localStorage.getItem(resourceExecutionPreviewStorage);if(raw&&raw.length>16384){localStorage.removeItem(resourceExecutionPreviewStorage);return [];}rows=JSON.parse(raw||'[]');if(!Array.isArray(rows)){localStorage.removeItem(resourceExecutionPreviewStorage);return [];}}catch{throw Error('原请求句柄无法读取，请恢复浏览器存储后再核对');}const valid=rows.filter(validResourceExecutionPreviewHandle);if(valid.length>8)throw Error('原请求句柄超出有界容量，须先明确核对已有请求');if(valid.length!==rows.length){if(valid.length)localStorage.setItem(resourceExecutionPreviewStorage,JSON.stringify(valid));else localStorage.removeItem(resourceExecutionPreviewStorage);}return valid;}
function sameResourceExecutionPreviewHandle(a,b){return !!a&&!!b&&['preparation','key','revision','source','expires'].every(k=>a[k]===b[k]);}
function currentResourceExecutionPreviewHandle(h){return validResourceExecutionPreviewHandle(h)&&resourceExecutionPreviewHandles().some(x=>sameResourceExecutionPreviewHandle(x,h));}
function saveResourceExecutionPreviewHandles(rows){if(rows.length>8||rows.some(h=>!validResourceExecutionPreviewHandle(h)))throw Error('原请求句柄已达容量，须先明确核对已有请求');try{if(rows.length)localStorage.setItem(resourceExecutionPreviewStorage,JSON.stringify(rows));else localStorage.removeItem(resourceExecutionPreviewStorage);}catch{throw Error('无法保存有界原请求句柄，请恢复浏览器存储后再预演');}}
function clearResourceExecutionPreview(){resourceExecutionPreviewGeneration++;resourceExecutionPreviewView=null;resourceExecutionPreviewHandle=null;resourceExecutionPreviewSubmitting=false;$('resource-execution-preview-panel').hidden=true;$('resource-execution-preview-result').replaceChildren();$('resource-execution-preview-error').textContent='';$('resource-execution-preview-run').disabled=true;}
function resourceExecutionPreviewControls(){const h=resourceExecutionPreviewHandle;$('resource-execution-preview-read').disabled=resourceExecutionPreviewSubmitting;$('resource-execution-preview-recover').disabled=resourceExecutionPreviewSubmitting;$('resource-execution-preview-run').disabled=!resourceExecutionPreviewView?.execution_available||!!h||resourceExecutionPreviewSubmitting;$('resource-execution-preview-recover').hidden=!h;$('resource-execution-preview-release').hidden=!h;$('resource-execution-preview-release').disabled=resourceExecutionPreviewSubmitting;}
