const bindingStates={CURRENT:'当前工程核对匹配',NEEDS_RECHECK:'需重新核对',PENDING:'尚未核对',CURRENT_BINDING_RECORD:'当前关联记录',HISTORICAL:'历史关联',CONFIRMED:'本地合成确认',CANCELLED:'已整组取消',RELEASED:'已释放',SUPPORTED_LOCAL:'支持本地协作目标',PARTIAL:'仍有未支持目标',UNKNOWN:'未知'};
function bindingValue(v){if(v===null||v===undefined)return '未记录';if(Array.isArray(v))return v.length?v.map(bindingValue).join('；'):'无';if(typeof v==='object'){if(v.request_text!==undefined)return '诉求：'+v.request_text+'；必需目标：'+bindingValue(v.required_goals)+'；覆盖：'+(bindingStates[v.coverage?.state]||v.coverage?.state||'未知');if(v.starts_at!==undefined)return '资源 '+String(v.resource_id||v.id||'').slice(0,8)+' · 规则版本 '+v.resource_revision+' · '+resourceTime(v.starts_at)+'—'+resourceTime(v.ends_at)+' UTC · '+v.quantity+'份 · '+(bindingStates[v.state]||v.state)+(v.expires_at?' · 来源占位期限 '+resourceTime(v.expires_at):'');if(v.capacity!==undefined)return '资源 '+String(v.id||'').slice(0,8)+' · 规则版本 '+v.revision+' · 容量 '+v.capacity+' · 开放 '+resourceTime(v.open_from)+'—'+resourceTime(v.open_until)+' UTC · '+(v.enabled?'启用':'停用');if(v.capability!==undefined)return '资源 '+String(v.resource_id||'').slice(0,8)+' · '+v.capability+' '+(v.active?'当前有效':'已撤回');if(v.kind!==undefined)return '来源 '+v.kind+' · '+(v.label||v.id||'未标明')+' · 版本 '+(v.revision??'未标明');return Object.entries(v).filter(([k])=>['revision','version','service_id','namespace','qualification','state'].includes(k)).map(([k,value])=>({revision:'版本',version:'版本',service_id:'服务',namespace:'范围',qualification:'资格',state:'状态'}[k])+': '+bindingValue(value)).join('；')||'来源内容已变化';}if(typeof v==='boolean')return v?'有效':'无效';const text=String(v);return bindingStates[text]||(/^[a-f0-9-]{32,64}$/.test(text)?text.slice(0,8)+'…':text);}
function bindingChangeText(change){if(typeof change==='string')return change;const path=change.path||change.field||change.code||'';const field=({combination_id:'资源组合',resource_link_id:'关联记录',resource_link_revision:'关联版本',request_intent_sha256:'诉求指纹',template_sha256:'工程模板指纹',service_id:'服务',service_version:'服务版本',owner_id:'经办人绑定',reviewer_id:'核对人绑定'}[path]||change.field||'来源版本');const old=change.before??change.old;const current=change.after??change.current??change.new;return field+'：'+bindingValue(old)+' → '+bindingValue(current);}
