let serviceReleasePreflightGeneration=0,serviceReleasePreflightDirectory=null,serviceReleasePreflightView=null,serviceReleasePreflightBusy=false,serviceReleasePreflightObserved=null;
const serviceReleasePreflightScope='OWNED_SYNTHETIC_SERVICE_RELEASE_PREFLIGHT';
function serviceReleasePreflightContext(){return {...servicePlanCtx(),preflightGeneration:serviceReleasePreflightGeneration,actor:servicePlanView?.actor_ref};}
function serviceReleasePreflightCurrent(c){return servicePlanCurrent(c)&&c.preflightGeneration===serviceReleasePreflightGeneration&&c.actor===servicePlanView?.actor_ref&&c.planId===servicePlanView?.plan_id&&c.revision===servicePlanView?.revision;}
function serviceReleasePreflightStorage(c){return 'parkweave.service-release-preflight.v1.'+c.id+'.'+c.actor;}
