function serviceReleasePreflightControls(){const x=servicePlanView,c=serviceReleasePreflightContext(),h=x?serviceReleasePreflightHandle(c):null,locked=serviceReleasePreflightBusy||!!servicePlanPending||!!servicePlanRecoveryHandle||servicePlanRecoveryChecking||x?.read_only===true; $('service-release-preflight-read').hidden=x?.role!=='enterprise_operator'||!x?.plan_id;$('service-release-preflight-read').disabled=locked;$('service-release-preflight-panel').hidden=!serviceReleasePreflightDirectory&&!h;$('service-release-preflight-preview').disabled=locked||!!h||!serviceReleasePreflightDirectory;$('service-release-preflight-save').disabled=locked||h!==null||!serviceReleasePreflightView?.can_record;$('service-release-preflight-recover').hidden=!h;$('service-release-preflight-recover').disabled=locked||h===false;$('service-release-preflight-release').hidden=!h||serviceReleasePreflightObserved!==JSON.stringify(h);$('service-release-preflight-release').disabled=locked;for(const id of ['original','target','reason','confirm'])$('service-release-preflight-'+id).disabled=locked||h!==null;}
