async function serviceReleasePreflightCall(c,suffix='',method='GET',body,key){if(!serviceReleasePreflightCurrent(c))return null;if(method==='POST')requireOriginalEntriesSettled();else if(!entryReadAllowed('service-release-preflight-read'))throw Error('请先在原入口核对尚未确定的操作');const headers={Authorization:'Bearer '+c.token};if(body)headers['Content-Type']='application/json';if(key)headers['Idempotency-Key']=key;const r=await fetch('/api/preparations/'+encodeURIComponent(c.id)+'/service-release-preflight'+suffix,{method,headers,cache:'no-store',body:body?JSON.stringify(body):undefined});if(!serviceReleasePreflightCurrent(c))return null;const x=await r.json();if(!serviceReleasePreflightCurrent(c))return null;if(r.status===403){if(x?.detail==='isolated service release preflight disabled'){clearServiceReleasePreflight();$('service-release-preflight-read').hidden=true;return null;}clearDeniedPrivateViews();return null;}if(!r.ok)throw Error(r.status===409?'来源、计划或原参数已变化；请只读核对原请求。':'预检请求未完成（HTTP '+r.status+'）');return x;}
