// Compact service selection has its own bounded, opaque original-key recovery handle.
let serviceSelectionGeneration=0,serviceSelectionCatalog=null,serviceSelectionView=null,serviceSelectionBusy=false;
const serviceSelectionStorage='parkweave.service-selection-original-key.v1.';
