function serviceSelectionContext(){return {...servicePlanCtx(),selectionGeneration:serviceSelectionGeneration,actor:servicePlanView?.actor_ref,requestRevision:servicePlanView?.request_revision};}
function serviceSelectionCurrent(c){return servicePlanCurrent(c)&&c.selectionGeneration===serviceSelectionGeneration&&c.actor===servicePlanView?.actor_ref&&c.prepareRevision===servicePlanView?.preparation_revision&&c.requestRevision===servicePlanView?.request_revision;}
