 const safe=['MESSAGE_LIMIT','SECRET_INPUT_REJECTED','INVALID_BUDGET','BUDGET_EXHAUSTED','PROPOSAL_LIVE_TRANSPORT_DISABLED','RATE_LIMIT_NO_RETRY','AUTHORIZATION_FAILED','HTTP_ERROR_NO_RETRY','INVALID_RESPONSE','SECRET_OUTPUT_REJECTED','INVALID_USAGE','MODEL_IDENTITY_MISMATCH','INVALID_ID','INVALID_CHOICES','TRUNCATED_NO_TOOL_EXECUTION','PROPOSAL_TOOL_OR_INCOMPLETE_RESPONSE','INVALID_PLANNER_PROPOSAL','INVALID_SERVICE_SELECTION','USAGE_RESERVATION_EXCEEDED','RESPONSE_LIMIT','SOURCE_OR_ATTEMPT_CHANGED','AUTHORIZATION_CHANGED'];
