function serviceSelectionIdentity(x,c){if(x.preparation_id!==c.id||x.case_id!==c.caseId||x.run_id!==c.runId||x.actor_ref!==c.actor||x.preparation_revision!==c.prepareRevision||x.request_revision!==c.requestRevision)throw Error('服务选择身份、事项或版本不匹配');}
