 for(const r of releases){if(!object(r)||!serviceSelectionPlanID(r.release_id)||releaseMap.has(r.release_id))fail();releaseMap.set(r.release_id,r);}
 for(const i of instances){if(!object(i)||!serviceSelectionPlanID(i.instance_id)||instanceMap.has(i.instance_id))fail();instanceMap.set(i.instance_id,i);}
