function serviceSelectionPreviewValidate(x,c){serviceSelectionIdentity(x,c);if(x.validator_version!==4||x.profile!=='TRUSTED_SERVICE_SELECTION_V4'||x.scope!=='SYNTHETIC_SERVICE_SELECTION_CANDIDATE'||!uuidHandle(x.candidate_id)||!/^[a-f0-9]{64}$/.test(x.candidate_sha256)||!/^[a-f0-9]{64}$/.test(x.verification_sha256)||!/^[a-f0-9]{64}$/.test(x.current_source_sha256)||!/^[a-f0-9]{64}$/.test(x.capability_catalog_sha256)||x.read_only!==true||x.provider_enabled!==false||x.execution_enabled!==false||x.new_grants!==false||x.case_goal_completed!==false||!Array.isArray(x.required_goals)||!Array.isArray(x.steps)||x.steps.length>5)throw Error('服务选择候选的版本或执行边界无法核对');if(serviceSelectionCatalog&&(x.current_source_sha256!==serviceSelectionCatalog.source_sha256||x.capability_catalog_sha256!==serviceSelectionCatalog.capability_catalog_sha256))throw Error('服务选择目录或来源已变化，须重新读取');if(!serviceSelectionCatalog||x.selection?.binding?.capability_catalog_sha256!==x.capability_catalog_sha256)throw Error('请先只读核对所选服务目录');serviceSelectionMetadata(x.selection,serviceSelectionCatalog.catalog_snapshot.releases,serviceSelectionCatalog.catalog_snapshot.instances);}
