function serviceSelectionAdoption(v,c,x){serviceSelectionPreviewValidate(v,serviceSelectionContext());const hs=serviceSelectionHandles();if(!$('service-selection-confirm').checked||hs===null||hs.length||!serviceSelectionCatalog||v.current_source_sha256!==serviceSelectionCatalog.source_sha256||v.capability_catalog_sha256!==serviceSelectionCatalog.capability_catalog_sha256||v.state!=='VERIFIED_STRUCTURE_ONLY'||v.can_adopt!==true||JSON.stringify(v.required_goals)!==JSON.stringify(x.current_preview?.required_goals)||$('plan-candidate-choice').value||x.can_adopt_partial||x.local_revision_required)throw Error('请核对当前精确服务选择候选并单独明确确认；未知不能采用');}

