async function generateServiceSelection(){if(serviceSelectionBusy)return;const c=serviceSelectionContext(),x=serviceSelectionCatalog,hs=serviceSelectionHandles();if(!x||!servicePlanView||servicePlanView.read_only||servicePlanView.can_adopt!==true||hs===null||hs.length||originalStoredWritePending()||servicePlanPending||servicePlanRecoveryHandle||!['UNIQUE','MULTIPLE'].includes(x.selection_oracle.state))throw Error('请先读取可信服务能力并GET核对所有原请求');serviceSelectionCatalogValidate(x,c);const h={v:1,id:c.id,actor:c.actor,case:c.caseId,run:c.runId,key:crypto.randomUUID()},name=serviceSelectionStorage+h.actor+'.'+h.key,raw=JSON.stringify(h);localStorage.setItem(name,raw);if(localStorage.getItem(name)!==raw||serviceSelectionHandles()===null)throw Error('原服务选择key保存失败，尚未发送');serviceSelectionBusy=true;serviceSelectionView=null;$('service-selection-confirm').checked=false;serviceSelectionControls();try{await servicePlanCall('/api/preparations/'+c.id+'/service-selections','POST',{expected_preparation_revision:c.prepareRevision,expected_source_sha256:x.source_sha256,expected_capability_catalog_sha256:x.capability_catalog_sha256},h.key,c);if(!serviceSelectionCurrent(c))return;serviceSelectionBusy=false;await recoverServiceSelection();}catch(e){if(serviceSelectionCurrent(c)){if(e.status===403)servicePlanError(e);else $('service-selection-status').textContent='原服务选择结果未核实，保留原key，只GET核对。'+e.message;}}finally{if(serviceSelectionCurrent(c)){serviceSelectionBusy=false;serviceSelectionControls();}}}
