function renderObjections(x){objectionView=x;$('objection-items').replaceChildren();$('objection-status').textContent=(x.current_review_valid?'':'须按原流程重开并由原专员重新审核当前来源。')+(x.unresolved?'存在未决或来源已变化的资料异议。':'当前没有未决资料异议；Case目标仍未完成。');const labels={OPEN:'企业异议待原专员回应',AWAITING_OWNER_REVIEW:'原专员已回应，等待企业明确复核',RESOLVED:'企业已明确接受当前回应',STALE:'来源已变化，保留历史，须重新绑定'};for(const t of x.items){const card=textElement('article','');card.dataset.objectionId=t.id;card.dataset.objectionState=t.state;card.append(textElement('strong',labels[t.state]),textElement('p','异议 '+t.id+' · v'+t.version+' · 原资料revision '+t.binding.preparation_revision+' · 原请求revision '+t.binding.request_revision));for(const m of t.binding.materials)card.append(textElement('small',m.slot+' · '+m.evidence_id+' / v'+m.version+' / SHA256 '+m.source_sha256));for(const h of t.history)card.append(textElement('p',h.action+' · '+h.actor_id+'：'+h.reason));const actions=x.role==='park_specialist'?(t.state==='OPEN'?['RESPOND']:[]):t.state==='AWAITING_OWNER_REVIEW'?['ACCEPT_RESPONSE','KEEP_OPEN']:t.state==='STALE'&&x.current_review_valid?['REBIND']:[];const names={RESPOND:'原获派专员回应',ACCEPT_RESPONSE:'企业复核：接受当前回应',KEEP_OPEN:'企业复核：异议仍未解决',REBIND:'企业明确绑定当前新版资料'};for(const action of actions){const b=textElement('button',names[action]);b.type='button';b.dataset.objectionAction=action;b.onclick=()=>objectionCommand(action,t).catch(objectionError);card.append(b);}$('objection-items').append(card);}objectionControls();}
async function loadObjections(c){requirePrepCurrent(c);objectionView=null;$('objection-items').replaceChildren();$('objection-raise').disabled=true;try{const x=await prepCall('/api/preparations/'+encodeURIComponent(c.id)+'/material-objections','GET',undefined,undefined,c);if(x.preparation_id!==c.id||x.case_id!==preparationContext?.caseId||x.preparation_revision!==preparationView?.preparation.revision)throw Error('异议与资料版本不匹配，请刷新');renderObjections(x);const handle=objectionHandle(x);if(handle){objectionPending={context:c,handle};objectionControls();}}catch(e){objectionError(e);}}
