async function recoverObjection(){const pending=objectionPending,c=pending?.context;if(!pending||objectionBusy)return;requirePrepCurrent(c);objectionBusy=true;objectionControls();try{const found=await prepCall('/api/preparations/'+encodeURIComponent(c.id)+'/material-objections/recovery/'+encodeURIComponent(pending.handle.key),'GET',undefined,undefined,c);if(found.preparation_id!==c.id||found.case_id!==preparationContext?.caseId||!found.historical_only||found.automatically_replayed)throw Error('恢复事件对象不匹配');if(found.status!=='COMMITTED'){objectionBusy=false;objectionControls();$('objection-error').textContent='尚未观察到原事件，原请求可能仍在途中；继续保留未知锁。';return;}if(found.event?.action!=='MATERIAL_OBJECTION'||found.event.revision!==pending.handle.revision+1||found.event.objection?.actor_id!==pending.handle.actor)throw Error('原事件身份或版本不匹配');const x=await prepCall('/api/preparations/'+encodeURIComponent(c.id)+'/material-objections','GET',undefined,undefined,c);const h=x.items.flatMap(t=>t.history).find(h=>h.event_id===found.event.objection.event_id);if(!h||Object.keys(found.event.objection).some(k=>JSON.stringify(h[k])!==JSON.stringify(found.event.objection[k])))throw Error('尚未核对到精确原事件');localStorage.removeItem(objectionStorage+c.id+'.'+pending.handle.actor);objectionPending=null;objectionBusy=false;await loadPreparation(c.id);$('objection-status').textContent='原操作已保存并只读核对；下方显示当前异议，历史事件不代表当前已解决。';$('objection-reason').value='';}catch(e){if(prepCurrent(c)){objectionBusy=false;objectionControls();}throw e;}}
