for(const eventName of ['click','submit'])document.addEventListener(eventName,e=>{if(!objectionLock())return;const target=e.target.closest('button,form');if(!target||target.id==='objection-recover'||target.id==='prep-refresh')return;e.preventDefault();e.stopImmediatePropagation();$('objection-error').textContent='原异议结果未知，请先只读核对原操作。';},true);

