function oppHandles(){try{const names=Object.keys(localStorage).filter(n=>n.startsWith(oppStorage));if(names.length>8)throw Error('capacity');return names.map(name=>{const raw=localStorage.getItem(name);if(!raw||raw.length>400)throw Error('corrupt');const h=JSON.parse(raw);if(!h||Array.isArray(h)||Object.keys(h).sort().join(',')!=='actor,id,key'||typeof h.actor!=='string'||!h.actor||h.actor.length>100||typeof h.id!=='string'||typeof h.key!=='string'||!uuidHandle(h.id)||!uuidHandle(h.key)||name!==oppStorage+h.actor+'.'+h.key)throw Error('corrupt');return {name,...h};});}catch(e){return null;}}
function oppDraft(){return JSON.stringify(['opp-family','opp-generation','opp-kind','opp-catalog','opp-title','opp-note','opp-reason'].map(id=>$(id).value).concat($('opp-purpose').checked));}
function oppCtx(withDraft=false){return {...prepContext(),oppGeneration,caseId:preparationView?.preparation.case_id,...(withDraft?{draft:oppDraft()}:{})};}
function oppCurrent(c){return prepCurrent(c)&&c.oppGeneration===oppGeneration&&c.caseId===preparationView?.preparation.case_id&&(c.draft===undefined||c.draft===oppDraft());}
function oppRequire(c){if(!oppCurrent(c)){const e=Error('已离开原机会事项或草稿');e.staleOpportunity=true;throw e;}}
function clearOpportunities(){clearPlanSourceConflict();const option=textElement('option','只读取与编辑人工说明');option.value='';$('plan-source-conflict-card').replaceChildren(option);clearOpportunityPlan();oppGeneration++;oppView=null;oppBusy=false;oppBusyContext=null;oppNewFamily=crypto.randomUUID();$('opportunity-panel').hidden=true;$('opp-import').reset();$('opp-reason').value='';for(const id of ['opp-cards','opp-history','opp-status','opp-error'])$(id).replaceChildren();}
function oppLocked(){const hs=oppHandles();return oppBusy||hs===null||hs.some(h=>h.id===preparationId&&(!oppView?.actor_id||h.actor===oppView.actor_id));}
function oppControls(){if(oppBusyContext&&!oppCurrent(oppBusyContext))oppBusy=false;const locked=oppLocked();$('opp-import-save').disabled=locked||!oppView?.can_write||!oppView.current_basis.catalog.length;$('opp-refresh').disabled=locked||!oppView?.can_write;$('opp-read').disabled=oppBusy;$('opp-recover').disabled=oppBusy||!oppView;for(const b of document.querySelectorAll('[data-opp-action],[data-opp-plan-preview]'))b.disabled=locked||!oppView?.can_write||opportunityPlanBusy;opportunityPlanControls();
 if(locked)$('opp-status').textContent=oppHandles()===null?'恢复句柄损坏或超界，保留存储；此事项机会新操作已暂停。':'原机会操作结果仍未知，请重新认证后只读核对；未观察到不代表未提交。';}
async function oppCall(path,method='GET',body,key,c=oppCtx()){oppRequire(c);const headers={Authorization:'Bearer '+c.token};if(body)headers['Content-Type']='application/json';if(key)headers['Idempotency-Key']=key;let r,x;try{r=await entryFetch(path,{method,headers,body:body?JSON.stringify(body):undefined});x=await r.json();}catch(e){oppRequire(c);e.opportunityContext=c;throw e;}oppRequire(c);if(!r.ok){const e=Error(r.status===403?'当前权限不能读取或办理本事项机会。':r.status===409?'机会版本、来源或状态已变化，请只读刷新核对。':r.status===422?'请核对合成来源、版本及说明。':'请求未完成，请保留原句柄只读核对。');e.status=r.status;e.opportunityContext=c;throw e;}return x;}
