  const names=ids=>ids.map(id=>servicePlanView.steps.find(s=>s.id===id)?.adapter_id||id).join('、')||'无';$('opp-plan-impact').append(textElement('p','当前计划 '+v.plan_id+' · 计划版本 '+v.plan_revision+' · 机会账本 '+v.opportunity_revision+' · 卡片版本 '+v.card_version),textElement('p','直接来源变化：'+names(v.directly_changed)),textElement('p','受影响、采纳后须原 VERIFY：'+names(v.affected)),textElement('p','保持原核验与人工锁证据：'+names(v.preserved)));
