 if(!v.can_adopt||v.blocking_reasons.length||v.unknown_scope||!v.affected.length||!card.source_binding_current||!card.current_catalog_available||card.state!=='PENDING_REVIEW'||!card.is_latest_generation||!a||a.local_revision!==true||a.expected_plan_revision!==x.revision||a.expected_preparation_revision!==x.preparation_revision||a.expected_request_revision!==x.request_revision||a.expected_source_sha256!==x.current_preview?.source_sha256||a.expected_source_sha256!==v.current_preview_source_sha256||JSON.stringify(a.required_goals)!==JSON.stringify(x.current_preview?.required_goals)||!p||p.card_id!==v.card_id||p.expected_ledger_revision!==v.opportunity_revision||p.expected_card_version!==v.card_version||p.expected_basis_sha256!==v.basis_sha256||p.expected_preview_sha256!==v.preview_sha256||$('plan-candidate-choice').value||serviceSelectionView)throw Error('来源、计划或选择状态已变化，请重新预览后明确采纳');
