async function opportunityPlanWrite(){requireOriginalEntriesSettled();const v=opportunityPlanView;if(!v)throw Error('请先读取来源对原计划的影响');await servicePlanWrite('ADOPT',null,v);opportunityPlanControls();}
$('opp-plan-confirm').onchange=opportunityPlanControls;$('opp-plan-adopt').onclick=()=>opportunityPlanWrite().catch(opportunityPlanError);
$('service-plan-reason').addEventListener('input',()=>{opportunityPlanDraftGeneration++;});
// Explicit owner notes use actual Case material text. They never change facts,
// contracts, locks, or business output proofs; those keep their original commands.
const planSourceConflictStorage='parkweave.plan-source-conflict.v1.';
