const approvalOldBundleControls=bundleControls;bundleControls=()=>{approvalOldBundleControls();planApprovalControls();};
const approvalOldClearResources=clearResources;clearResources=()=>{planApprovalView=null;planApprovalSelected=null;planApprovalBusy=false;planApprovalBusyContext=null;planApprovalEnabled=false;$('plan-approval-result').replaceChildren();$('plan-approval-error').textContent='';approvalOldClearResources();};
bundleIdentify=async c=>{const [x,status]=await Promise.all([resourceCall('/api/resource-bundles','GET',undefined,undefined,c),resourceCall('/api/plan-approval/status','GET',undefined,undefined,c)]);if(!resourceCurrent(c)){const e=Error('身份已变化');e.staleResource=true;throw e;}if(typeof x.actor_id!=='string')throw Error('组合身份响应不匹配');bundleActor=x.actor_id;planApprovalEnabled=status.enabled===true;bundleControls();return x;};
function planApprovalRender(x,c){if(x.actor_id!==bundleActor||x.preparation_id!==c.id||x.scope!=='ISOLATED_SYNTHETIC_CASE_RESOURCE_APPROVAL_V1'||!Array.isArray(x.items)||x.items.length>8||!Number.isInteger(x.revision))throw Error('原Case批准响应不匹配');
 x={...x,items:x.items.map(item=>Date.now()>=Date.parse(item.valid_until)?{...item,current:false,current_available:false,delivery:null,context:null}:item)};
 planApprovalView=x;planApprovalSelected=x.items.at(-1)||null;const target=$('plan-approval-result');target.replaceChildren();
 const title=document.createElement('p');title.textContent='此Case批准记录版本 '+x.revision+'；真实执行仍未启用。';target.append(title);
 const labels={PROPOSED:'已提出，待明确批准',APPROVED:'已批准',REVOKED:'已明确撤销',CONSUMED:'已用于原交付，历史保留'};
 for(const item of x.items){const p=document.createElement('p');p.textContent=(labels[item.state]||'未知状态')+' · '+(item.current?'本次来源仍有效':'当前不能提交，需重新核对')+' · 期限 '+item.valid_until+' · 批准编号 '+item.id;target.append(p);
  const detail=document.createElement('p');detail.textContent='原执行身份 '+item.execution_identity.actor_id+'；Run '+item.execution_identity.run.id+'；服务 '+item.service_id+' / '+item.service_version+'；计划指纹 '+item.plan_sha256+'；材料版本 '+item.materials.map(m=>m.slot+' v'+m.version).join('，');target.append(detail);
  for(const member of item.members){const row=document.createElement('p');row.textContent='资源 '+member.resource_id+' 修订 '+member.resource_revision+'，'+member.quantity+' 份，'+member.starts_at+' 至 '+member.ends_at;target.append(row);}}
 const item=planApprovalSelected;if(item?.current&&item.delivery&&item.context&&JSON.stringify(item.delivery.members)===c.members){
  const d=item.delivery;deliveryQuote={context:c,view:{context:item.context,expected_preparation_revision:d.expected_preparation_revision,expected_plan_revision:d.expected_plan_revision,source_sha256:d.expected_source_sha256,valid_until:d.valid_until,synthetic_plan_approval_required:true}};
 }bundleControls();}
