 await bundleIdentify(c.resource);requireDeliveryCurrent(c);const hs=planApprovalHandles();if(hs===null)throw Error('原批准恢复句柄不可核对；请保留记录并从原事项人工核对');const h=selected||hs.find(h=>h.actor===bundleActor&&(!c.id||h.id===c.id));if(!h)throw Error('当前身份与Case没有待核对的原批准操作');planApprovalRequireHandle(h);
 if(!c.id){$('delivery-case').value=h.id;c=deliveryContext();planApprovalBusyContext=c;}if(h.id!==c.id||h.actor!==bundleActor)throw Error('原批准Case或身份不匹配');
