 if(x.status!=='COMMITTED')throw Error('尚未观察到原批准操作；这不表示失败，请保留原句柄继续只读核对');const e=x.event;
 if(e?.actor_id!==h.actor||e?.request_key!==h.key||e?.action!==h.action||e?.revision!==h.revision+1||(h.approval_id!==null&&e.approval_id!==h.approval_id))throw Error('原批准事件证明不匹配');
