 const hs=planApprovalHandles();if(!hs||hs.length>=8||hs.some(h=>h.actor===bundleActor))throw Error('请先核对已有原操作');const started=Date.now(),h={v:1,actor:bundleActor,id:c.id,key:crypto.randomUUID(),action,approval_id:action==='PROPOSE'?null:planApprovalSelected.id,revision:data.expected_revision,started,expires:started+86400000};name=planApprovalStorage+h.actor+'.'+h.key;const raw=JSON.stringify(h);localStorage.setItem(name,raw);if(localStorage.getItem(name)!==raw)throw Error('恢复句柄未保存，尚未发送');phase='POST';
