$('plan-approval-read').onclick=async()=>{const c=deliveryContext();planApprovalBusy=true;planApprovalBusyContext=c;bundleControls();try{await bundleIdentify(c.resource);requireDeliveryCurrent(c);if(!/^[a-f0-9-]{36}$/.test(c.id))throw Error('请输入原Case资料事项编号');const x=await deliveryCall('/api/preparations/'+c.id+'/plan-approval','GET',undefined,undefined,c);planApprovalRender(x,c);$('plan-approval-error').textContent='';}catch(e){if(deliveryCurrent(c)){$('plan-approval-result').replaceChildren();planApprovalView=null;planApprovalSelected=null;deliveryQuote=null;$('plan-approval-error').textContent=e.message;}resourceError(e);}finally{if(deliveryCurrent(c)){planApprovalBusy=false;bundleControls();}}};
