let receiptHistoryGeneration=0;
function receiptHistoryCanonical(x){if(Array.isArray(x))return '['+x.map(receiptHistoryCanonical).join(',')+']';if(x!==null&&typeof x==='object')return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+receiptHistoryCanonical(x[k])).join(',')+'}';return JSON.stringify(x);}
