for(const id of ['token','receipt-history-preparation','receipt-history-key'])$(id).addEventListener('input',clearReceiptHistory);
$('receipt-history-read').onclick=async()=>{
 const c={generation:receiptHistoryGeneration,token:$('token').value.trim(),id:$('receipt-history-preparation').value.trim(),key:$('receipt-history-key').value.trim()};
 const current=()=>c.generation===receiptHistoryGeneration&&c.token===$('token').value.trim()&&c.id===$('receipt-history-preparation').value.trim()&&c.key===$('receipt-history-key').value.trim();
 $('receipt-history-result').replaceChildren();$('receipt-history-error').textContent='';$('receipt-history-read').disabled=true;
 try{
  if(!c.token||!/^[0-9a-f-]{36}$/i.test(c.id)||!c.key)throw Error('请填写当前身份、原资料事项编号和原请求编号。');
  const response=await entryFetch('/api/preparations/'+encodeURIComponent(c.id)+'/receipt-execution-history/recovery/'+encodeURIComponent(c.key),{headers:{Authorization:'Bearer '+c.token}});if(!current())return;if(response.status===403){clearDeniedPrivateViews();return;}const x=await response.json();
  if(!current())return;
  if(!response.ok)throw Error(response.status===403?'当前原授权不可用，历史保持不可读。':response.status===409?'原历史证明无法核对，保持未知。':'只读核对暂不可用，请检查原服务后再次读取。');
  if(x.read_only!==true||x.history_transport!=='ISOLATED_P4_LIVE_ISSUER_HISTORY_GET_V1'||x.preparation_id!==c.id||x.scope!=='ISOLATED_REGISTERED_P4_RECEIPT_EXECUTION_PREVIEW'||x.formal_writes!==0||x.automatically_replayed!==false)throw Error('原历史响应无法核对。');
  const box=$('receipt-history-result');
  if(x.status==='NOT_OBSERVED'){if(x.result!==null)throw Error('原请求响应无法核对。');box.append(textElement('p','原请求尚未观察到提交，保持未决；不会自动重放。'));return;}
  if(x.status!=='COMMITTED'||!x.result||x.result.request_key!==c.key||x.result.scope!==x.scope||x.result.namespace!==x.namespace||x.result.binding?.preparation_id!==c.id||x.result.formal_writes!==0||!Array.isArray(x.history)||x.history.filter(v=>receiptHistoryCanonical(v.document)===receiptHistoryCanonical(x.result)).length!==1)throw Error('原请求编号与历史响应无法核对，保持未知。');
  const d=x.result,a=d.artifact,old=x.history.find(v=>v.document.id===d.id),r=a.p4_receipts[0],report=r?.adapter_execution?.report;
  box.append(textElement('strong','原报告 '+a.p4_state+' · '+(old?.source_state||'UNKNOWN')),textElement('p','企业决定 '+d.review_decision+' · 原事件 '+a.p4_events.map(v=>v.action).join('→')));
  if(report)box.append(textElement('p','执行编号 '+report.execution_id+' · 回执版本 '+r.version+' · hash '+r.source_sha256));
  if(a.p4_state==='CHANGES_REQUESTED')box.append(textElement('p','企业要求纠正，当前尚未核对；不会自动重新生成或ACK。'));
  box.append(textElement('p','接单一致性元数据报告，不代表真实材料服务交付或真人批准。'),textElement('p','保留全部目标：'+d.required_goals.join('；')+'。P5未执行，Case未完成。'),textElement('p','PENDING通知意图 '+a.outbox.length+'，未消费；正式业务写入0。'));
 }catch(e){if(current()){$('receipt-history-result').replaceChildren();$('receipt-history-error').textContent=e.message;}}
 finally{if(current())$('receipt-history-read').disabled=false;}
};

