const coldStorage='parkweave.cold-input-original-key.v1',coldStages=['CREATE_RUN','CREATE_PREPARATION','SAVE_REQUEST','ADD_need_summary','ADD_material_outline'];
const coldGoalLabels={LOCAL_MATERIAL_PREPARATION:'本地资料准备',LOCAL_CASE_RESOURCE_ASSOCIATION:'本事项资源关联',LOCAL_INTERNAL_ACCEPTANCE:'内部分派与接单',LOCAL_SYNTHETIC_RECEIPT_ACKNOWLEDGEMENT:'合成回执核对',LOCAL_SYNTHETIC_COORDINATION_RECORDS:'合成协作记录',LOCAL_CASE_RECORD_RECHECK:'本地事项记录重核'};
let coldDirectory=null,coldView=null,coldBusy=false,coldGeneration=0,coldChosen=null;
function coldKeys(x,keys){return x&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).sort().join(',')===keys.slice().sort().join(',');}
function coldText(x,n){return typeof x==='string'&&x.trim()===x&&x.length>0&&x.length<=n;}
function coldHandle(){const raw=localStorage.getItem(coldStorage);if(raw===null)return null;let h;try{h=JSON.parse(raw);}catch{throw Error('原新事项句柄损坏，保留记录并人工核对');}if(raw.length>640||!coldKeys(h,['v','actor','key','sent'])||h.v!==1||!coldText(h.actor,100)||!uuidHandle(h.key)||!Array.isArray(h.sent)||h.sent.length>10||new Set(h.sent).size!==h.sent.length||h.sent.some(x=>!['PREPARE',...coldStages,...coldStages.slice(1).map(name=>'PREPARE_STAGE:'+name)].includes(x)))throw Error('原新事项句柄不完整，不能发送');return h;}
function coldRemember(h){const text=JSON.stringify(h);localStorage.setItem(coldStorage,text);if(localStorage.getItem(coldStorage)!==text)throw Error('恢复句柄未安全保存，尚未发送');}
function coldUnresolved(){try{const h=coldHandle();return !!h&&(!coldView||h.actor!==coldView.actor_ref||h.key!==coldView.request_key||coldStages.some(name=>!coldCommitted(name)) );}catch{return true;}}
function coldContext(){return {token:$('token').value,generation:coldGeneration};}
function coldCurrent(c){return c.token===$('token').value&&c.generation===coldGeneration;}
function coldClear(){coldGeneration++;coldDirectory=null;coldView=null;coldChosen=null;coldBusy=false;for(const id of ['cold-goal','cold-extra','cold-need','cold-outline','cold-reason'])$(id).value='';$('cold-goals').replaceChildren();$('cold-instance').replaceChildren();$('cold-stage').replaceChildren();$('cold-binding').textContent='';$('cold-command').textContent='';$('cold-observations').textContent='';$('cold-input-history').replaceChildren();$('cold-form').hidden=true;$('cold-current').hidden=true;$('cold-prepare-confirm').checked=false;$('cold-send-confirm').checked=false;coldControls();}
function coldError(e,c){if(!coldCurrent(c))return;if(e.status===403){clearDeniedPrivateViews();$('cold-status').textContent='当前访问被拒绝，私有输入已清除；原请求编号保留，只能在恢复有权身份后GET核对。';}else{$('cold-status').textContent=e.message;coldControls();}}
async function coldCall(c,path,method='GET',body,key){if(!coldCurrent(c))throw Error('已离开原身份');const headers={Authorization:'Bearer '+c.token};if(key)headers['Idempotency-Key']=key;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch(path,{method,headers,cache:'no-store',...(body===undefined?{}:{body:JSON.stringify(body)})});if(!coldCurrent(c))throw Error('迟到响应已忽略');if(!response.ok){const e=Error('原请求未确认（HTTP '+response.status+'），请仅GET核对原编号');e.status=response.status;throw e;}const x=await response.json();if(!coldCurrent(c))throw Error('迟到响应已忽略');return x;}
function coldFlags(x){return x.read_only===true&&x.automatically_replayed===false&&x.provider_enabled===false&&x.execution_enabled===false&&x.new_grants===false&&x.automatic_adoption===false;}
function coldDirectoryCheck(x){if(x.scope!=='SYNTHETIC_PARK_INSTANCE_COLD_INPUT_DIRECTORY'||!coldText(x.actor_ref,100)||!coldText(x.park_id,100)||!coldFlags(x)||typeof x.has_unknown_sources!=='boolean'||!Array.isArray(x.instances)||x.instances.length>16||!Array.isArray(x.allowed_goals)||x.allowed_goals.length>6||new Set(x.allowed_goals).size!==x.allowed_goals.length||x.allowed_goals.some(g=>!Object.hasOwn(coldGoalLabels,g)))throw Error('当前配置目录范围无法核实');const ids=new Set(),all=new Set();for(const i of x.instances){if(!coldKeys(i,['instance_id','config_revision','config_sha256','release_id','release_revision','release_sha256','service_id','title','supported_goals','fields'])||!coldText(i.instance_id,100)||ids.has(i.instance_id)||!Number.isInteger(i.config_revision)||i.config_revision<1||i.config_revision>64||!Number.isInteger(i.release_revision)||i.release_revision<1||i.release_revision>64||!coldText(i.release_id,100)||!/^[a-f0-9]{64}$/.test(i.config_sha256)||!/^[a-f0-9]{64}$/.test(i.release_sha256)||!['synthetic-material-preparation','synthetic-resource-coordination','synthetic-local-record-recheck'].includes(i.service_id)||!coldText(i.title,200)||!Array.isArray(i.supported_goals)||!i.supported_goals.length||i.supported_goals.length>6||new Set(i.supported_goals).size!==i.supported_goals.length||i.supported_goals.some(g=>!Object.hasOwn(coldGoalLabels,g))||!coldKeys(i.fields,['need_summary','material_outline'])||!Object.values(i.fields).every(f=>coldText(f,100))||i.fields.need_summary===i.fields.material_outline)throw Error('精确配置字段无法核实');ids.add(i.instance_id);i.supported_goals.forEach(g=>all.add(g));}if([...all].sort().join(',')!==x.allowed_goals.slice().sort().join(','))throw Error('目录目标集合无法核实');}
function coldCanonical(x){if(Array.isArray(x))return '['+x.map(coldCanonical).join(',')+']';if(x&&typeof x==='object')return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+coldCanonical(x[k])).join(',')+'}';return JSON.stringify(x);}
async function coldDigest(x){const bytes=new TextEncoder().encode(coldCanonical(x));return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');}
function coldStageBodyCheck(x,stage){const b=stage.body,i=x.input,instance=x.binding.instance;let expected;if(stage.name==='CREATE_RUN')expected={schema_version:'parkweave-domain/0.1',action:'case.create',goal:i.goal,source:'SYNTHETIC'};else if(stage.name==='CREATE_PREPARATION'){const run=x.product_observations.find(o=>o.name==='CREATE_RUN'&&o.status==='COMMITTED')?.result;expected={run_id:run?.run_id,service_id:'synthetic-material-preparation',service_version:1,reviewer_id:instance?.roles?.park_specialist};}else if(stage.name==='SAVE_REQUEST'){if(!Number.isInteger(b.expected_preparation_revision)||b.expected_preparation_revision<1||b.expected_preparation_revision>64)throw Error('原资料版本无法核实');expected={expected_preparation_revision:b.expected_preparation_revision,request_text:i.goal,required_goals:i.required_goals,planning_constraints:i.planning_constraints};}else{const slot=stage.name.slice(4),material=Object.values(i.fields||{}).find(m=>m.slot===slot);if(!material||!Number.isInteger(b.expected_revision)||b.expected_revision<1||b.expected_revision>64)throw Error('原新材料版本无法核实');expected={action:'ADD_EVIDENCE',expected_revision:b.expected_revision,...material};}if(coldCanonical(b)!==coldCanonical(expected))throw Error('原阶段正文与本次新输入不匹配');}
function coldInputCheck(x){const input=x.input;if(!coldText(input.goal,2000)||!Array.isArray(input.required_goals)||input.required_goals.length<1||input.required_goals.length>8||new Set(input.required_goals).size!==input.required_goals.length||input.required_goals.some(g=>!coldText(g,160))||!input.fields||Object.keys(input.fields).length!==2)throw Error('原诉求或必需目标无法核实');const materials=Object.values(input.fields);if(new Set(materials.map(m=>m?.slot)).size!==2||materials.some(m=>!coldKeys(m,['slot','text','source_kind','source_label'])||!['need_summary','material_outline'].includes(m.slot)||!coldText(m.text,4000)||!coldText(m.source_label,200)||!['USER_STATEMENT','DOCUMENT_EXCERPT'].includes(m.source_kind)))throw Error('两项原新材料无法核实');}
async function coldCheck(x,h){if(x.scope!=='SYNTHETIC_PARK_INSTANCE_COLD_INPUT'||x.actor_ref!==h.actor||x.request_key!==h.key||!coldText(x.park_id,100)||!coldFlags(x)||x.automatic_execution!==false||x.business_publication!==false||x.case_goal_completed!==false||typeof x.current_available!=='boolean'||!uuidHandle(x.cold_input_id)||x.binding?.kind!=='PARK_INSTANCE_COLD_INPUT_V1'||!x.input||!Array.isArray(x.stages)||x.stages.length<1||x.stages.length>5||!Array.isArray(x.product_observations)||x.product_observations.length!==x.stages.length)throw Error('原新事项回执范围不匹配，句柄保留');coldInputCheck(x);if(!coldText(x.binding.instance?.roles?.enterprise_operator,100)||await coldDigest({actor_id:x.binding.instance.roles.enterprise_operator})!==h.actor)throw Error('原企业主体与opaque身份不匹配');const seen=new Set(),keys=new Set();for(const stage of x.stages){if(!coldStages.includes(stage.name)||seen.has(stage.name)||keys.has(stage.request_key)||stage.request_key!=='tc_'+x.cold_input_id.replace(/-/g,'')+'_'+stage.name||stage.state!=='ADMITTED'||!/^[a-f0-9]{64}$/.test(stage.body_sha256)||!stage.body||stage.body_sha256!==await coldDigest(stage.body))throw Error('原阶段正文指纹无法核实');coldStageBodyCheck(x,stage);const obs=x.product_observations.find(o=>o.name===stage.name);if(!obs||obs.request_key!==stage.request_key||obs.automatically_replayed!==false||obs.not_committed_final!==false||!['COMMITTED','NOT_OBSERVED'].includes(obs.status)||(obs.status==='NOT_OBSERVED'&&obs.result!==null)||(obs.status==='COMMITTED'&&(!obs.result||typeof obs.result!=='object')))throw Error('原阶段观察无法核实');seen.add(stage.name);keys.add(stage.request_key);}if(!seen.has('CREATE_RUN')||new Set(x.product_observations.map(o=>o.name)).size!==x.stages.length)throw Error('原建单阶段缺失');const run=x.product_observations.find(o=>o.name==='CREATE_RUN');if(run.status==='COMMITTED'&&(!uuidHandle(run.result.run_id)||!['QUEUED','RUNNING','PAUSED','RECONCILING','WAITING_APPROVAL','SUCCEEDED','FAILED','CANCELLED','UNKNOWN'].includes(run.result.run_state)))throw Error('原运行观察无法核实');for(const obs of x.product_observations.filter(o=>o.name!=='CREATE_RUN'&&o.status==='COMMITTED'))if(!uuidHandle(obs.result.preparation_id)||obs.result.actor_id!==x.binding.instance?.roles?.enterprise_operator||obs.result.scope!=='SYNTHETIC_LOCAL_PREPARATION_ONLY')throw Error('原资料事件主体无法核实');if(coldDirectory&&(coldDirectory.actor_ref!==h.actor||coldDirectory.park_id!==x.park_id))throw Error('当前目录与原回执主体不同');}
function coldCommitted(name){const o=coldView?.product_observations.find(o=>o.name===name);return o?.status==='COMMITTED'&&(name!=='CREATE_RUN'||o.result.run_state==='SUCCEEDED');}
function coldWritable(){const i=coldView?.binding.instance;return !!coldDirectory&&!!coldView&&coldView.current_available&&coldDirectory.actor_ref===coldView.actor_ref&&coldDirectory.park_id===coldView.park_id&&coldDirectory.instances.some(row=>row.instance_id===i?.instance_id&&row.config_revision===i?.config_revision&&row.config_sha256===i?.config_sha256&&row.release_id===i?.release_id&&row.release_sha256===i?.release_sha256);}
function coldNext(){return coldStages.find(name=>!coldCommitted(name));}
function coldPath(name){if(name==='CREATE_RUN')return '/api/runs';if(name==='CREATE_PREPARATION')return '/api/preparations';const prep=coldView?.product_observations.find(o=>o.name==='CREATE_PREPARATION'&&o.status==='COMMITTED')?.result.preparation_id;if(!uuidHandle(prep))throw Error('尚无精确新资料事项观察');return '/api/preparations/'+prep+(name==='SAVE_REQUEST'?'/request-intent':'/commands');}
function coldControls(){let h;try{h=coldHandle();}catch{}const selected=coldView?.stages.find(s=>s.name===$('cold-stage').value),next=coldNext();$('cold-prepare').disabled=coldBusy||!coldDirectory||!!h||!$('cold-prepare-confirm').checked;$('cold-stage-prepare').disabled=coldBusy||!coldWritable()||!next||next==='CREATE_RUN'||$('cold-stage').value!==next||h?.sent.includes('PREPARE_STAGE:'+next)||coldView.stages.some(s=>s.name===next);$('cold-stage-send').disabled=coldBusy||!coldWritable()||!selected||selected.name!==next||h?.sent.includes(selected.name)||!$('cold-send-confirm').checked;$('cold-open').disabled=coldBusy||!coldWritable()||!coldStages.every(coldCommitted);$('cold-new').disabled=coldBusy||!coldStages.every(coldCommitted);$('cold-directory-read').disabled=coldBusy;$('cold-recover').disabled=coldBusy||!h;}
function coldRender(){const x=coldView;$('cold-current').hidden=!x;if(!x)return;const history=$('cold-input-history');history.replaceChildren();history.append(textElement('p','原诉求：'+x.input.goal),textElement('p','全部原必需目标：'+x.input.required_goals.join('；')));for(const slot of ['need_summary','material_outline']){const m=Object.values(x.input.fields).find(m=>m.slot===slot);history.append(textElement('h4',slot==='need_summary'?'原新诉求材料':'原新资料清单'),textElement('p',m.text),textElement('small','来源：'+m.source_label+' · '+m.source_kind));}$('cold-observations').textContent=x.product_observations.map(o=>o.name+'：'+o.status+(o.name==='CREATE_RUN'&&o.result?' / '+o.result.run_state:'')).join('；');$('cold-stage').replaceChildren();const next=coldNext();if(next)$('cold-stage').append(new Option(next,next));$('cold-stage').value=next||'';$('cold-send-confirm').checked=false;coldShowCommand();$('cold-status').textContent=!coldWritable()?'当前仅可只读核对原输入与阶段历史；须显式读取本人仍有权的当前配置，才能进入办理入口。':next?'请明确准备并提交一个原阶段。已发送但未观察到仍属未知；只能GET核对，不能重发。':'五个原阶段已核实；可打开此新事项，另行明确选择与采用。';coldControls();}
function coldShowCommand(){coldChosen=null;const stage=coldView?.stages.find(s=>s.name===$('cold-stage').value);$('cold-command').textContent=stage?'POST '+coldPath(stage.name)+'\nIdempotency-Key: '+stage.request_key+'\n'+JSON.stringify(stage.body,null,2):'此阶段尚未准备；不会自动发送。';if(stage)coldChosen=stage.name;$('cold-send-confirm').checked=false;coldControls();}
async function coldRecoverAt(c,h){const x=await coldCall(c,'/api/service-instance-cold-inputs/recovery','GET',undefined,h.key);await coldCheck(x,h);if(!coldCurrent(c))return;coldView=x;coldRender();return x;}
async function coldRecover(){const c=coldContext();try{if(coldBusy)return;const h=coldHandle();if(!h)throw Error('没有原新事项请求编号');coldBusy=true;coldControls();await coldRecoverAt(c,h);}catch(e){coldError(e,c);}finally{if(coldCurrent(c)){coldBusy=false;coldControls();}}}
async function coldReadDirectory(){const c=coldContext();try{if(coldBusy)return;coldBusy=true;coldControls();const x=await coldCall(c,'/api/service-instance-configurations');coldDirectoryCheck(x);if(!coldCurrent(c))return;if(coldView&&(coldView.actor_ref!==x.actor_ref||coldView.park_id!==x.park_id))throw Error('目录与已读原请求主体不同');coldDirectory=x;$('cold-instance').replaceChildren();x.instances.forEach(i=>$('cold-instance').append(new Option(i.title+' · '+i.instance_id,i.instance_id)));$('cold-instance').value=x.instances[0]?.instance_id||'';$('cold-goals').replaceChildren();for(const [goal,label] of Object.entries(coldGoalLabels)){const row=textElement('label',label),check=document.createElement('input');check.type='checkbox';check.dataset.coldGoal=goal;check.disabled=!x.allowed_goals.includes(goal);row.append(check);$('cold-goals').append(row);}$('cold-form').hidden=false;coldInstanceChanged();$('cold-status').textContent=x.has_unknown_sources?'部分来源未知；仅列当前本人可用配置。未知不会变成已满足。':'已读取当前配置；每项原命令仍须单独确认。';}catch(e){coldError(e,c);}finally{if(coldCurrent(c)){coldBusy=false;coldControls();}}}
function coldInstanceChanged(){const i=coldDirectory?.instances.find(i=>i.instance_id===$('cold-instance').value);$('cold-binding').textContent=i?i.service_id+' · 配置v'+i.config_revision+' '+i.config_sha256+' · 发布v'+i.release_revision+' '+i.release_sha256+' · 新诉求材料→'+i.fields.need_summary+'；新资料清单→'+i.fields.material_outline:'';$('cold-prepare-confirm').checked=false;coldControls();}
function coldNewWriteAllowed(){if(activeEntryWriteFlow||entryWriteRequests.size||originalStoredWritePending())throw Error('请先GET核对其他原入口尚未确定的操作');}
async function coldPrepare(){const c=coldContext();try{if(coldBusy)return;if(coldHandle())throw Error('已有原请求；只能GET核对，不创建第二请求');coldNewWriteAllowed();const d=coldDirectory,i=d?.instances.find(i=>i.instance_id===$('cold-instance').value);if(!i||!$('cold-prepare-confirm').checked)throw Error('请先读取配置并明确只准备原请求');const required_goals=[...$('cold-goals').querySelectorAll('input[data-cold-goal]')].filter(el=>el.checked).map(el=>el.dataset.coldGoal).concat($('cold-extra').value.split('\n').map(x=>x.trim()).filter(Boolean));if(!required_goals.length||required_goals.length>8||new Set(required_goals).size!==required_goals.length||required_goals.some(g=>!coldText(g,160)))throw Error('请明确填写1至8个不同必需目标');const goal=$('cold-goal').value.trim(),reason=$('cold-reason').value.trim(),fields={};if(!coldText(goal,2000)||!coldText(reason,1000))throw Error('请填写本次诉求和明确原因');for(const [slot,id] of [['need_summary','cold-need'],['material_outline','cold-outline']]){const text=$(id).value.trim();if(!coldText(text,4000))throw Error('请填写两项新材料纯文本');fields[i.fields[slot]]={slot,text,source_kind:'USER_STATEMENT',source_label:'本次新输入：'+slot};}const body={instance_id:i.instance_id,expected_config_revision:i.config_revision,expected_config_sha256:i.config_sha256,expected_release_id:i.release_id,expected_release_sha256:i.release_sha256,goal,required_goals,fields,reason};const h={v:1,actor:d.actor_ref,key:crypto.randomUUID(),sent:['PREPARE']};coldRemember(h);coldBusy=true;coldControls();try{await coldCall(c,'/api/service-instance-cold-inputs','POST',body,h.key);}catch(e){if(e.status===403)throw e;if(!coldCurrent(c))return;$('cold-status').textContent='准备响应未知；原编号保留，仅GET核对。';}await coldRecoverAt(c,h);}catch(e){coldError(e,c);}finally{if(coldCurrent(c)){coldBusy=false;coldControls();}}}
