async function coldSendStage(){const c=coldContext();try{if(coldBusy)return;const h=coldHandle(),name=$('cold-stage').value,stage=coldView?.stages.find(s=>s.name===name);if(!h||!coldWritable()||!stage||name!==coldNext()||name!==coldChosen||h.sent.includes(name)||!$('cold-send-confirm').checked)throw Error('须明确确认当前原命令；已发送或未知阶段不能重发');if(activeEntryWriteFlow||entryWriteRequests.size||originalStoredWritePending(true))throw Error('请先核对其他在途原操作');const path=coldPath(name);h.sent.push(name);coldRemember(h);coldBusy=true;coldControls();try{await coldCall(c,path,'POST',stage.body,stage.request_key);}catch(e){if(e.status===403)throw e;if(!coldCurrent(c))return;$('cold-status').textContent='原命令响应未知；不重发，仅GET原key核对。';}await coldRecoverAt(c,h);}catch(e){coldError(e,c);}finally{if(coldCurrent(c)){coldBusy=false;coldControls();}}}
function coldResolveHandle(){const h=coldHandle();if(coldBusy||!h||!coldView||h.actor!==coldView.actor_ref||h.key!==coldView.request_key||!coldStages.every(coldCommitted))throw Error('须先GET核实全部原阶段，才能结束这次输入');localStorage.removeItem(coldStorage);if(localStorage.getItem(coldStorage)!==null)throw Error('原核对句柄未安全清理');}
