function clearBoundedCaseReads(){boundedCaseReadEpoch++;boundedCaseReadView=null;for(const id of ['simulation-rule-result','case-time-result','case-resource-recovery-result'])$(id).replaceChildren();for(const id of ['simulation-rule-status','case-time-status'])$(id).textContent='';}
function boundedCaseContext(){if(!preparationView||!preparationContext||prepRole!=='enterprise_operator')throw Error('请先以所属企业身份读取当前资料事项');requirePrepCurrent(preparationContext);const p=preparationView.preparation;return {...prepContext(),epoch:boundedCaseReadEpoch,caseId:p.case_id,revision:p.revision,owner:p.owner_id};}
