function caseTimeAnchors(c){if(!servicePlanView||servicePlanView.preparation_id!==c.id||servicePlanView.case_id!==c.caseId||servicePlanView.preparation_revision!==c.revision||!uuidHandle(servicePlanView.plan_id)||!caseResourceView||caseResourceView.case_id!==c.caseId||caseResourceView.preparation_revision!==c.revision||!caseResourceView.current)throw Error('请先明确读取当前办理计划和原资源关联');const old=caseResourceView.current,ids=old.combination?.members?.map(m=>m.resource_id);if(!Array.isArray(ids)||ids.length!==2||new Set(ids).size!==2||ids.some(id=>!uuidHandle(id)))throw Error('原关联不是精确两资源');if(!servicePlanView.binding||!Array.isArray(servicePlanView.required_goals)||servicePlanView.required_goals.length!==6||new Set(servicePlanView.required_goals).size!==6||servicePlanView.required_goals.some(g=>!Object.hasOwn(coldGoalLabels,g)))throw Error('原六目标及当前采用绑定无法核实');return {binding:coldCanonical(servicePlanView.binding),goals:servicePlanView.required_goals.slice().sort(),plan:servicePlanView.plan_id,revision:servicePlanView.revision,link:caseResourceView.link_revision,group:old.combination.id,resources:ids.sort()};}
